export default function Skills() {
  const [activeTab, setActiveTab] = useState('all');

  const categories = [
    { id: 'all', label: 'All' },
    { id: 'frontend', label: 'Frontend' },
    { id: 'backend', label: 'Backend' },
    { id: 'database', label: 'Database' },
    { id: 'tools', label: 'Tools & Design' },
  ];

  const skillList = [
    { name: 'HTML', category: 'frontend', icon: <Icons.HTML /> },
    { name: 'CSS', category: 'frontend', icon: <Icons.CSS /> },
    { name: 'React', category: 'frontend', icon: <Icons.React /> },
    { name: 'Tailwind CSS', category: 'frontend', icon: <Icons.Tailwind /> },
    { name: 'PHP', category: 'backend', icon: <Icons.PHP /> },
    { name: 'Laravel', category: 'backend', icon: <Icons.Laravel /> },
    { name: 'Python', category: 'backend', icon: <Icons.Python /> },
    { name: 'SQL', category: 'database', icon: <Icons.SQL /> },
    { name: 'MySQL', category: 'database', icon: <Icons.MySQL /> },
    { name: 'VS Code', category: 'tools', icon: <Icons.VSCode /> },
    { name: 'GitHub', category: 'tools', icon: <Icons.GitHub /> },
    { name: 'Postman', category: 'tools', icon: <Icons.Postman /> },
    { name: 'MS Office', category: 'tools', icon: <Icons.MSOffice /> },
    { name: 'Canva', category: 'tools', icon: <Icons.Canva /> },
  ];

  const filteredSkills = activeTab === 'all'
    ? skillList
    : skillList.filter((s) => s.category === activeTab);

  // Palet baris konsisten:
  // Sebelahan (dalam 1 baris 4 kolom di desktop): Warna SAMA
  // Atas-bawah (antar baris bergantian): Warna BEDA
  const rowThemes = [
    {
      accentBar: 'bg-cyan-500',
      headerBg: 'bg-cyan-50/85 dark:bg-[#06202e] border-b border-cyan-200/80 dark:border-cyan-900/60',
      badge: 'bg-cyan-100 text-cyan-800 dark:bg-cyan-950 dark:text-cyan-300 border border-cyan-300/80 dark:border-cyan-700/50',
      readyText: 'text-cyan-700 dark:text-cyan-400',
      readyDot: 'bg-cyan-500',
    },
    {
      accentBar: 'bg-indigo-500',
      headerBg: 'bg-indigo-50/85 dark:bg-[#121936] border-b border-indigo-200/80 dark:border-indigo-900/60',
      badge: 'bg-indigo-100 text-indigo-800 dark:bg-indigo-950 dark:text-indigo-300 border border-indigo-300/80 dark:border-indigo-700/50',
      readyText: 'text-indigo-700 dark:text-indigo-400',
      readyDot: 'bg-indigo-500',
    },
  ];

  return (
    <section id="skills" className="py-14 sm:py-20 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto">
      
      {/* Title & Filter Tabs */}
      <SectionReveal>
        <div className="text-center space-y-2 mb-8 sm:mb-10">
          <h2 className="text-2xl sm:text-4xl font-extrabold text-slate-900 dark:text-white font-bankai">
            <span className="text-cyan-600 dark:text-cyan-400">SKILL</span>
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-transparent via-cyan-500 to-transparent mx-auto" />
        </div>

        <div className="flex flex-wrap justify-center gap-1.5 sm:gap-2 mb-8 sm:mb-10">
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveTab(cat.id)}
              className={`px-3 py-1.5 sm:px-4 sm:py-2 rounded-xl text-[11px] sm:text-xs font-mono transition-all cursor-pointer ${
                activeTab === cat.id
                  ? 'bg-cyan-600 dark:bg-cyan-500 text-white font-bold shadow-sm border border-cyan-400/50'
                  : 'bg-white dark:bg-white/5 border border-slate-200 dark:border-white/10 text-slate-600 dark:text-gray-300 hover:border-cyan-500 hover:text-slate-900 dark:hover:text-white shadow-xs'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>
      </SectionReveal>

      {/* Skills Grid: 4 items per row on desktop (sebelahan sama, atas-bawah beda) */}
      <SectionReveal delay={120}>
        <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-4 gap-3.5 sm:gap-4">
          {filteredSkills.map((skill, index) => {
            // Hitung baris (4 kolom per baris di tablet & desktop)
            const rowIndex = Math.floor(index / 4);
            const theme = rowThemes[rowIndex % rowThemes.length];

            return (
              <div
                key={index}
                className="reiatsu-card rounded-xl overflow-hidden flex flex-col justify-between group transition-all hover:border-cyan-500/50 dark:hover:border-cyan-400/50 shadow-xs hover:shadow-md"
              >
                {/* 1. Solid Top Accent Bar */}
                <div className={`h-1 w-full ${theme.accentBar}`} />

                {/* 2. Top Header Block: Solid Color */}
                <div className={`p-3.5 sm:p-4 ${theme.headerBg}`}>
                  <div className="flex items-center justify-between">
                    <div className="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center group-hover:scale-110 transition-transform">
                      {skill.icon}
                    </div>
                    <span className={`text-[10px] font-mono px-2 py-0.5 rounded capitalize font-bold ${theme.badge}`}>
                      {skill.category}
                    </span>
                  </div>
                </div>

                {/* 3. Skill Card Body */}
                <div className="p-3.5 sm:p-4 flex-1 flex flex-col justify-between">
                  <h3 className="font-bold text-slate-800 dark:text-white text-sm sm:text-base group-hover:text-cyan-600 dark:group-hover:text-cyan-300 transition-colors">
                    {skill.name}
                  </h3>
                  
                  <div className="mt-3 pt-2.5 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[10px] sm:text-[11px] font-mono">
                    <span className={`${theme.readyText} font-semibold`}>Ready</span>
                    <span className={`w-1.5 h-1.5 rounded-full ${theme.readyDot} animate-pulse`} />
                  </div>
                </div>

              </div>
            );
          })}
        </div>
      </SectionReveal>
    </section>
  );
}
